public class Mosaik1
{
   Rectangle rahmen;
   Rectangle [][] füllung; // TODO0 Hier siehst du wie ein zweidimensionales Array erstellt wird. 


   // Festgelegte Werte für Randabstand und Kästchengröße 
   static final int RAND_ABSTAND = 200; 
   static final int KÄSTCHEN_GRÖSSE = 200; 

    /**
     * Konstruktor für Objekte der Klasse Mosaik.
     */
   Mosaik1()
   {
      rahmen = new Rectangle(100, 100, 1200, 1200); 
      rahmen.setFillColor(Color.gray);

      // TODO 1: Initialisiere das Array mit passender Größe für Kästchen der Größe 200. Beachte die Größe des Rahmens und den Rand Abstand. 
      füllung = new Rectangle[5][5]; 


      neuesMosaik();
   }

    /**
     * Diese Methode erzeugt ein Mosaik. 
     */
   void neuesMosaik() 
   {
      // TODO 2a Umgib die folgende Wiederholung mit einer zweiten für Zählvariable x. 

      for (int y = 0; y < füllung[0].length; y++) {
            // TODO 2b Das Array muss mit den Mosaikfließen befüllt werden. 
            //       Nutze die Methode erstelleQuadrat(seitenLaenge, x, y). 
            //       Bedenke, dass die einzelnen Fließen immer weiter verschoben werden 
            //       müssen in Abhängigkeit von x und y. 
         füllung[0][y] = erstelleQuadrat(KÄSTCHEN_GRÖSSE, RAND_ABSTAND,(y * KÄSTCHEN_GRÖSSE) + RAND_ABSTAND);
      }

   } 

   /**
     * Diese Methode erzeugt ein Quadrat und zeichnet es.
     * 
     * @param seitenLaenge Die Seitenlaenge des Quadrats. 
     * @param x Die x-Position des Quadrats. 
     * @param y Die y-Position des Quadrats.
     * @param farbe Die Farbe des Quadrats.
     */
   private Rectangle erstelleQuadrat(int seitenLaenge, int x, int y)
   {
      Rectangle rechteck = new Rectangle(x, y, seitenLaenge, seitenLaenge); 
      rechteck.setFillColor(Color.randomColor());
      //println(rechteck.getFillColor());
      return rechteck;
   }

}

