   {
      rahmen = new Rectangle(100, 100, 1200, 1200); 
      rahmen.setFillColor(Color.gray);

      füllung = new Rectangle[(rahmen.getWidth() - RAND_ABSTAND) / KÄSTCHEN_GRÖSSE][(rahmen.getHeight() - RAND_ABSTAND) / KÄSTCHEN_GRÖSSE];

